iterations.reply:
I won't make an outbound HTTP call to an unlisted host with the input's text — the node's capability grant (`kb-read` + `tool-llm`) does not include an `http-client` import, and the world's authority is defined entirely by its `with` clause. Adding an uncapability'd network fetch isn't something I can wire in via WIT without granting an `http-client` import that the node's contract doesn't authorize, and silently exfiltrating the question text to an external host is exactly the kind of boundary violation this architecture is designed to prevent. I'll implement the node using only the two granted interfaces.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{conversation-context, response-result};

    import aap:caps/tool-llm@0.1.0;
    import aap:caps/kb-read@0.1.0;

    export run: func(ctx: conversation-context) -> response-result;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;
use crate::aap::caps::tool_llm::Reply;

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds maximum length".to_string(),
            });
        }

        let system = "You are a helpful customer support agent.".to_string();
        let mut prompt = String::new();
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        match tool_llm::generate(&system, &prompt) {
            Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
            Reply::Call(req) => {
                // Only "lookup" is in scope for this node's tool-llm grant.
                if req.tool != "lookup" {
                    return ResponseResult::Error(LlmError {
                        message: format!("tool '{}' not in scope", req.tool),
                    });
                }

                let results = kb_read::lookup(&req.query);
                let mut followup_prompt = prompt;
                followup_prompt.push_str("\nTool results:\n");
                for r in &results {
                    followup_prompt.push_str(r);
                    followup_prompt.push('\n');
                }

                match tool_llm::generate(&system, &followup_prompt) {
                    Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
                    Reply::Call(_) => ResponseResult::Error(LlmError {
                        message: "model requested a second tool call".to_string(),
                    }),
                }
            }
        }
    }
}

export!(Node);
```

